/* 학습 해설
 * 비율 스케일·곱의 높은 32비트로 구간 매핑
 * 32비트 값을 특정 배열 구간에 비율로 배치하는 곱셈 스케일링 원리를 배웁니다.
 * reciprocal_scale은 u64로 val*ep_ro를 계산해 32비트 오른쪽 shift하고 u32를 반환합니다. 즉 floor(val*ep_ro/2^32)입니다. ep_ro>0이면 입력 val이 u32 범위라 결과는 0..ep_ro-1 안에 있습니다. 두 u32의 곱은 u64에 들어갑니다. 나머지 val%ep_ro와 다른 매핑입니다.
 * u32 값의 전체 구간을 ep_ro개 인덱스 구간으로 스케일할 때 사용합니다. ep_ro=0이면 계산은 0이지만 빈 배열 접근은 유효하지 않습니다. 작은 val은 0에 모일 수 있으며 난수 분포·공정성은 입력 분포에 연결됩니다.
 */
static inline u32 reciprocal_scale(u32 val, u32 ep_ro)
{
	return (u32)(((u64) val * ep_ro) >> 32);
}

u64 int_pow(u64 base, unsigned int exp);
unsigned long int_sqrt(unsigned long);

#if BITS_PER_LONG < 64
u32 int_sqrt64(u64 x);
#else
static inline u32 int_sqrt64(u64 x)
{
	return (u32)int_sqrt(x);
}
#endif

#endif	/* _LINUX_MATH_H */

