/* 학습 해설
 * 정수 수학 선언 연결·sqrt64의 조건부 본문
 * 공개 수학 헤더가 정수 거듭제곱·제곱근 구현과 빌드 폭을 연결하는 방법을 배웁니다.
 * math.h는 int_pow(u64,unsigned int)와 int_sqrt(unsigned long)를 선언합니다. BITS_PER_LONG<64에서는 int_sqrt64(u64)의 외부 선언을, 64비트 long에서는 int_sqrt(x)를 u32로 변환하는 inline 본문을 제공합니다. u64 제곱근의 최대 바닥값은 2^32-1이라 u32 반환에 들어갑니다.
 * 입력 폭에 맞는 API로 호출하고 lib/math/int_pow.c·int_sqrt.c의 수업과 연결합니다. long32 구성의 별도 u64 본문과 long64의 inline 호출을 같은 함수 중복 구현이라고 혼동하지 않습니다.
 */
u32 int_sqrt64(u64 x);
#else
static inline u32 int_sqrt64(u64 x)
{
	return (u32)int_sqrt(x);
}
#endif

#endif	/* _LINUX_MATH_H */

