/* 학습 해설
 * CPU별 근사 카운터·중앙 합계와 로컬 잔여값
 * 여러 CPU가 같은 숫자를 자주 바꿀 때 중앙 변수 경쟁을 줄이는 자료구조를 배웁니다.
 * CONFIG_SMP 구조체는 raw spinlock, s64 중앙 count, s32 per-CPU counters를 가집니다. CPU별 작은 변경은 로컬에 모으고 batch 경계를 넘으면 중앙으로 합칩니다. HOTPLUG 구성은 전역 관리 목록용 list도 포함합니다. 중앙 count만 읽으면 아직 합치지 않은 로컬 값을 빠뜨리므로 근사값입니다.
 * 쓰기 빈도가 높고 정확한 합계 읽기가 상대적으로 드문 카운터에 사용합니다. count와 각 로컬 값의 합을 표로 추적하고 메모리 비용·오차·동기화 비용을 함께 평가합니다. 단일 atomic 변수와 결과 읽기 비용이 다릅니다.
 */
struct percpu_counter {
	raw_spinlock_t lock;
	s64 count;
#ifdef CONFIG_HOTPLUG_CPU
	struct list_head list;	/* All percpu_counters are on a list */
#endif
	s32 __percpu *counters;
};

extern int percpu_counter_batch;

int __percpu_counter_init_many(struct percpu_counter *fbc, s64 amount,
			       gfp_t gfp, u32 nr_counters,
			       struct lock_class_key *key);

#define percpu_counter_init_many(fbc, value, gfp, nr_counters)		\
	({								\
		static struct lock_class_key __key;			\
									\
		__percpu_counter_init_many(fbc, value, gfp, nr_counters,\
					   &__key);			\
	})


#define percpu_counter_init(fbc, value, gfp)				\
	percpu_counter_init_many(fbc, value, gfp, 1)

