/* 학습 해설
 * CPU별 카운터 배열 초기화·공유 할당의 요소 간격
 * 여러 카운터를 하나의 per-CPU 할당에 배치하고 실패 상태를 관리하는 방법을 배웁니다.
 * 초기화는 s32 크기를 정렬한 counter_size와 nr_counters를 곱해 한 per-CPU 블록을 할당합니다. 각 fbc[i]는 같은 블록의 i*counter_size 위치를 counters 포인터로 가리키고 중앙 count=amount를 저장합니다. 할당 실패는 fbc[0].counters=NULL과 -ENOMEM을 반환하며 이후 초기화를 하지 않습니다.
 * 양수 nr_counters와 충분한 fbc 배열, 할당 곱의 표현 범위를 준비하고 반환을 확인합니다. 실패 시 모든 항목이 완전히 초기화됐다고 가정하지 않습니다. 성공한 묶음의 개수·첫 포인터를 해제까지 일관되게 유지합니다.
 */
int __percpu_counter_init_many(struct percpu_counter *fbc, s64 amount,
			       gfp_t gfp, u32 nr_counters,
			       struct lock_class_key *key)
{
	unsigned long flags __maybe_unused;
	size_t counter_size;
	s32 __percpu *counters;
	u32 i;

	counter_size = ALIGN(sizeof(*counters), __alignof__(*counters));
	counters = __alloc_percpu_gfp(nr_counters * counter_size,
				      __alignof__(*counters), gfp);
	if (!counters) {
		fbc[0].counters = NULL;
		return -ENOMEM;
	}

	for (i = 0; i < nr_counters; i++) {
		raw_spin_lock_init(&fbc[i].lock);
		lockdep_set_class(&fbc[i].lock, key);
#ifdef CONFIG_HOTPLUG_CPU
		INIT_LIST_HEAD(&fbc[i].list);
#endif
		fbc[i].count = amount;
		fbc[i].counters = (void __percpu *)counters + i * counter_size;

