/* 학습 해설
 * 카운터 초기화 매크로·호출 지점 lockdep 클래스
 * 동일한 잠금 코드라도 호출 지점별 정적 key로 잠금 검증 정보를 구분하는 기술을 배웁니다.
 * SMP 초기화 매크로는 statement expression 안에 static struct lock_class_key __key를 선언하고 내부 초기화 함수에 &__key를 전달합니다. C 구현은 각 항목 lock을 초기화하고 lockdep_set_class로 같은 key를 설정합니다. 단일 init은 nr_counters=1 wrapper입니다.
 * 공개 init/init_many를 사용해 잠금 검증 key와 초기화를 연결합니다. key는 runtime 상호 배제 자체가 아니라 lockdep 분류용 정보이며 포인터만 전달한다고 spinlock 기능이 대체되지는 않습니다.
 */
#define percpu_counter_init_many(fbc, value, gfp, nr_counters)		\
	({								\
		static struct lock_class_key __key;			\
									\
		__percpu_counter_init_many(fbc, value, gfp, nr_counters,\
					   &__key);			\
	})


#define percpu_counter_init(fbc, value, gfp)				\
	percpu_counter_init_many(fbc, value, gfp, 1)

void percpu_counter_destroy_many(struct percpu_counter *fbc, u32 nr_counters);
static inline void percpu_counter_destroy(struct percpu_counter *fbc)
{
	percpu_counter_destroy_many(fbc, 1);
}

void percpu_counter_set(struct percpu_counter *fbc, s64 amount);
void percpu_counter_add_batch(struct percpu_counter *fbc, s64 amount,
			      s32 batch);
s64 __percpu_counter_sum(struct percpu_counter *fbc);
int __percpu_counter_compare(struct percpu_counter *fbc, s64 rhs, s32 batch);
bool __percpu_counter_limited_add(struct percpu_counter *fbc, s64 limit,
				  s64 amount, s32 batch);
void percpu_counter_sync(struct percpu_counter *fbc);

