/* 학습 해설
 * 카운터 묶음 해제·첫 포인터의 소유권
 * 공유 할당을 한 번 해제하고 관리 목록과 사용 상태를 정리하는 생명주기를 배웁니다.
 * destroy_many는 NULL fbc를 WARN 후 반환하고 첫 counters가 NULL이면 반환합니다. 성공 묶음은 debug 비활성화와 hotplug 목록 제거 후 fbc[0].counters를 한 번 free_percpu하고 모든 counters를 NULL로 만듭니다. 단일 destroy wrapper는 개수 1이며 initialized는 SMP에서 counters!=NULL을 검사합니다.
 * init_many와 같은 시작 배열·개수로 destroy_many를 호출하고 사용자를 먼저 종료합니다. 묶음 중간 항목에 단일 destroy를 적용하면 내부 offset 포인터를 free할 수 있어 소유권 계약을 위반합니다. 해제 후 접근은 허용되지 않습니다.
 */
void percpu_counter_destroy_many(struct percpu_counter *fbc, u32 nr_counters)
{
	unsigned long flags __maybe_unused;
	u32 i;

	if (WARN_ON_ONCE(!fbc))
		return;

	if (!fbc[0].counters)
		return;

	for (i = 0; i < nr_counters; i++)
		debug_percpu_counter_deactivate(&fbc[i]);

#ifdef CONFIG_HOTPLUG_CPU
	spin_lock_irqsave(&percpu_counters_lock, flags);
	for (i = 0; i < nr_counters; i++)
		list_del(&fbc[i].list);
	spin_unlock_irqrestore(&percpu_counters_lock, flags);
#endif

	free_percpu(fbc[0].counters);

	for (i = 0; i < nr_counters; i++)
		fbc[i].counters = NULL;
}

