annotated:
/* 학습 해설
 * 로컬 비교교환 batch·IRQ 사이의 결정과 갱신
 * 로컬 값을 읽고 빠른 경로를 결정한 뒤 인터럽트가 끼어들 수 있는 문제를 배웁니다.
 * HAVE_CMPXCHG_LOCAL 경로는 count를 읽고 abs(count+amount)>=batch이면 IRQ를 막고 중앙 lock 안에서 현재 CPU 로컬을 다시 읽어 중앙에 합칩니다. 그보다 작은 값은 this_cpu_try_cmpxchg로 읽은 값과 같을 때만 로컬 갱신합니다. 실패하면 최신 기대값으로 조건을 다시 판단해 IRQ 갱신 사이의 잘못된 batch 초과를 피합니다.
 * 양수 batch와 s32 로컬·s64 중간값의 표현 범위를 지켜 add_batch를 호출합니다. local cmpxchg는 공용 중앙 변수의 모든 CPU atomic 교환과 목적이 다르며 느린 경로의 재읽기는 CPU 이동·값 변경을 반영합니다.
 */
void percpu_counter_add_batch(struct percpu_counter *fbc, s64 amount, s32 batch)
{
	s64 count;
	unsigned long flags;

	count = this_cpu_read(*fbc->counters);
	do {
		if (unlikely(abs(count + amount) >= batch)) {
			raw_spin_lock_irqsave(&fbc->lock, flags);
			/*
			 * Note: by now we might have migrated to another CPU
			 * or the value might have changed.
			 */
			count = __this_cpu_read(*fbc->counters);
			fbc->count += count + amount;
			__this_cpu_sub(*fbc->counters, count);
			raw_spin_unlock_irqrestore(&fbc->lock, flags);
			return;
		}
	} while (!this_cpu_try_cmpxchg(*fbc->counters, &count, count + amount));
}
