/* 학습 해설
 * IRQ 차단 batch fallback·조건 검사와 수정의 한 구간
 * 로컬 비교교환 지원이 없을 때 인터럽트 차단으로 같은 문제를 해결하는 기술을 배웁니다.
 * !HAVE_CMPXCHG_LOCAL 경로는 local_irq_save부터 restore까지 로컬 읽기·batch 판단·갱신을 묶습니다. 경계를 넘으면 중앙 raw lock에서 count를 합치고 기존 로컬값 count-amount를 뺍니다. 아니면 this_cpu_add로 amount를 더합니다. 중앙 lock과 IRQ 차단은 서로 다른 경쟁 대상을 처리합니다.
 * 동일 API라도 CONFIG에 따라 선택되는 두 본문을 비교합니다. IRQ 차단은 현재 CPU의 구간이고 raw spinlock은 중앙 공유값 보호입니다. 오버플로·batch 범위는 두 경로 모두 caller가 지킵니다.
 */
void percpu_counter_add_batch(struct percpu_counter *fbc, s64 amount, s32 batch)
{
	s64 count;
	unsigned long flags;

	local_irq_save(flags);
	count = __this_cpu_read(*fbc->counters) + amount;
	if (abs(count) >= batch) {
		raw_spin_lock(&fbc->lock);
		fbc->count += count;
		__this_cpu_sub(*fbc->counters, count - amount);
		raw_spin_unlock(&fbc->lock);
	} else {
		this_cpu_add(*fbc->counters, amount);
	}
	local_irq_restore(flags);
}
#endif
EXPORT_SYMBOL(percpu_counter_add_batch);

