/* 학습 해설
 * 근사 비교의 오차 경계·가까우면 전체 합산
 * 거친 값만으로 비교가 확정되는 경우 비싼 합산을 피하는 알고리즘을 배웁니다.
 * compare는 중앙 read와 rhs 차이가 batch*num_online_cpus보다 크면 중앙값의 대소만 반환합니다. 경계보다 멀어 오차가 방향을 뒤집지 않는다는 전제입니다. 차이가 작거나 같으면 전체 sum을 계산해 1·0·-1을 반환합니다. 공개 compare wrapper는 기본 percpu_counter_batch를 전달합니다.
 * 로컬 잔여값을 해당 batch 범위 안에 유지하는 갱신 규약과 산술 범위를 함께 지킵니다. LOCAL_BATCH로 크게 쌓은 값에 작은 기본 batch의 오차 한계를 그대로 적용하지 않습니다. 정확도를 위해 필요한 sum 호출을 선택합니다.
 */
int __percpu_counter_compare(struct percpu_counter *fbc, s64 rhs, s32 batch)
{
	s64	count;

	count = percpu_counter_read(fbc);
	/* Check to see if rough count will be sufficient for comparison */
	if (abs(count - rhs) > (batch * num_online_cpus())) {
		if (count > rhs)
			return 1;
		else
			return -1;
	}
	/* Need to use precise count */
	count = percpu_counter_sum(fbc);
	if (count > rhs)
		return 1;
	else if (count < rhs)
		return -1;
	else
		return 0;
}
