/* 학습 해설
 * 제한 카운터 빠른 갱신·전체 불확실성 범위
 * 제한을 넘지 않는 증가·감소를 근사 범위로 먼저 판정하는 사용 방법을 배웁니다.
 * limited_add는 amount=0이면 true를 반환합니다. 그 외 IRQ를 막고 unknown=batch*온라인CPU수와 현재 로컬을 읽습니다. abs(local+amount)<=batch이며 양수에서 중앙+unknown<=limit 또는 음수에서 중앙-unknown>=limit이면 로컬만 갱신합니다. 로컬 범위 안이라는 조건과 전체 불확실성 한계로 중앙 lock을 피합니다.
 * 양수 amount는 최종값<=limit, 음수 amount는 최종값>=limit 요구로 사용합니다. 값·limit·amount는 S64 극단에서 멀리 떨어진 sane 범위와 해당 batch 규약을 지킵니다. limit는 음수도 허용되지만 방향 의미를 명확히 합니다.
 */
bool __percpu_counter_limited_add(struct percpu_counter *fbc,
				  s64 limit, s64 amount, s32 batch)
{
	s64 count;
	s64 unknown;
	unsigned long flags;
	bool good = false;

	if (amount == 0)
		return true;

	local_irq_save(flags);
	unknown = batch * num_online_cpus();
	count = __this_cpu_read(*fbc->counters);

	/* Skip taking the lock when safe */
	if (abs(count + amount) <= batch &&
	    ((amount > 0 && fbc->count + unknown <= limit) ||
	     (amount < 0 && fbc->count - unknown >= limit))) {
		this_cpu_add(*fbc->counters, amount);
		local_irq_restore(flags);
		return true;
	}

	raw_spin_lock(&fbc->lock);
	count = fbc->count + amount;

