/* 학습 해설
 * 기본 batch 조정·온라인 CPU 수와 최소 32
 * 기본 batching 크기를 CPU 규모에 맞춰 조정하는 정책과 사용 한계를 배웁니다.
 * 전역 percpu_counter_batch는 초기 32이고 compute_batch_value는 max(32,num_online_cpus()*2)로 갱신합니다. CPU가 적으면 최소 32, 많아지면 CPU 수에 비례합니다. wrapper add·compare·limited_add가 이 기본 값을 사용하지만 add_local은 INT_MAX의 별도 batch를 사용합니다.
 * CPU 수에 따른 batch와 예상 중앙 갱신 빈도·읽기 오차를 계산합니다. runtime 감소 뒤 잔여값을 즉시 새 batch로 자동 줄인다고 가정하지 말고 sync와 상위 규약을 고려합니다.
 */
static int compute_batch_value(unsigned int cpu)
{
	int nr = num_online_cpus();

	percpu_counter_batch = max(32, nr*2);
	return 0;
}

static int percpu_counter_cpu_dead(unsigned int cpu)
{
#ifdef CONFIG_HOTPLUG_CPU
	struct percpu_counter *fbc;

	compute_batch_value(cpu);

	spin_lock_irq(&percpu_counters_lock);
	list_for_each_entry(fbc, &percpu_counters, list) {
		s32 *pcount;

		raw_spin_lock(&fbc->lock);
		pcount = per_cpu_ptr(fbc->counters, cpu);
		fbc->count += *pcount;
		*pcount = 0;
		raw_spin_unlock(&fbc->lock);
	}
	spin_unlock_irq(&percpu_counters_lock);

