/* 학습 해설
 * 카운터 hotplug 초기 등록·호출 여부가 다른 두 상태
 * 모듈 초기화가 CPU 상태 callback을 연결하고 오류를 관찰하는 방법을 배웁니다.
 * startup은 CPUHP_AP_ONLINE_DYN에 compute_batch_value를 등록하고 반환 ret<0이면 WARN합니다. 이어 setup_state_nocalls로 CPUHP_PERCPU_CNT_DEAD의 teardown callback을 등록해 현재 CPU에 즉시 호출하지 않는 경로를 선택합니다. 두 경고 후 함수는 0을 반환하며 module_init이 초기화에 연결합니다.
 * CPU online 정책 갱신과 dead 잔여 fold를 각각의 상태·방향에 연결합니다. WARN이 있다고 초기화가 반드시 실패 errno를 반환하거나 이전 등록을 rollback한다고 읽지 않습니다.
 */
static int __init percpu_counter_startup(void)
{
	int ret;

	ret = cpuhp_setup_state(CPUHP_AP_ONLINE_DYN, "lib/percpu_cnt:online",
				compute_batch_value, NULL);
	WARN_ON(ret < 0);
	ret = cpuhp_setup_state_nocalls(CPUHP_PERCPU_CNT_DEAD,
					"lib/percpu_cnt:dead", NULL,
					percpu_counter_cpu_dead);
	WARN_ON(ret < 0);
	return 0;
}
module_init(percpu_counter_startup);

