/* 학습 해설
 * 로컬 전용 카운터 갱신·INT_MAX batch와 드문 읽기
 * 중앙 합산을 최대한 늦추는 local API의 용도와 필수 읽기 방식을 배웁니다.
 * add_local은 PERCPU_COUNTER_LOCAL_BATCH=INT_MAX를 add_batch에 전달합니다. sub_local은 -amount를 같은 local 경로로 전달합니다. 일반 add·limited_add·compare는 기본 batch를 쓰는 wrapper입니다. 큰 local batch는 쓰기 효율을 높이지만 중앙 read에 대부분의 잔여값이 빠질 수 있습니다.
 * 갱신이 매우 많고 읽기가 드문 경우 local add/sub와 전체 sum을 함께 사용합니다. s32 경계와 signed -amount overflow를 피하며 default batch의 비교 오차 가정을 local 모드에 무조건 적용하지 않습니다.
 */
percpu_counter_add_local(struct percpu_counter *fbc, s64 amount)
{
	percpu_counter_add_batch(fbc, amount, PERCPU_COUNTER_LOCAL_BATCH);
}

static inline s64 percpu_counter_sum_positive(struct percpu_counter *fbc)
{
	s64 ret = __percpu_counter_sum(fbc);
	return ret < 0 ? 0 : ret;
}

static inline s64 percpu_counter_sum(struct percpu_counter *fbc)
{
	return __percpu_counter_sum(fbc);
}

static inline s64 percpu_counter_read(struct percpu_counter *fbc)
{
	return fbc->count;
}

