/* 학습 해설
 * 단일 CPU 카운터·배열 없이 IRQ-safe 중앙 변경
 * CPU가 하나인 구성에서 같은 API를 더 단순한 상태로 구현하는 방법을 배웁니다.
 * !SMP는 count 하나만 가지며 init_many는 각 fbc[i].count=amount 후 0을 반환합니다. destroy 계열과 sync는 빈 본문이고 initialized는 true입니다. add는 local_irq_save 안에서 count+=amount를 실행합니다. add_local/add_batch는 같은 add로 연결해 batch 인수를 사용하지 않습니다.
 * CONFIG_SMP가 없는 헤더 본문을 별도로 읽고 per-CPU 배열 할당·중앙/로컬 오차를 그 구성에 추가하지 않습니다. IRQ 재진입 갱신은 여전히 관리하며 signed 합의 범위를 caller가 확인합니다.
 */
percpu_counter_add(struct percpu_counter *fbc, s64 amount)
{
	unsigned long flags;

	local_irq_save(flags);
	fbc->count += amount;
	local_irq_restore(flags);
}

static inline bool
percpu_counter_limited_add(struct percpu_counter *fbc, s64 limit, s64 amount)
{
	unsigned long flags;
	bool good = false;
	s64 count;

	if (amount == 0)
		return true;

	local_irq_save(flags);
	count = fbc->count + amount;
	if ((amount > 0 && count <= limit) ||
	    (amount < 0 && count >= limit)) {
		fbc->count = count;
		good = true;
	}

