/* 학습 해설
 * 단일 CPU 제한 갱신·정확한 count와 상·하한
 * 단일 값 구성에서 제한 검사를 실제 후보 합으로 직접 수행하는 방법을 배웁니다.
 * !SMP limited_add는 amount=0이면 true를 반환하고 IRQ 구간에서 count=fbc->count+amount를 계산합니다. 양수이면 후보<=limit, 음수이면 후보>=limit일 때만 대입하고 good=true를 반환합니다. UP compare는 count와 rhs를 직접 비교하며 __compare의 batch는 무시합니다.
 * 증가 상한·감소 하한을 후보값 기준으로 테스트하고 거절 시 원래 count 보존을 확인합니다. 후보 합의 signed overflow를 피합니다. SMP의 unknown 범위·online mask 합산을 이 경로에 추가하지 않습니다.
 */
percpu_counter_limited_add(struct percpu_counter *fbc, s64 limit, s64 amount)
{
	unsigned long flags;
	bool good = false;
	s64 count;

	if (amount == 0)
		return true;

	local_irq_save(flags);
	count = fbc->count + amount;
	if ((amount > 0 && count <= limit) ||
	    (amount < 0 && count >= limit)) {
		fbc->count = count;
		good = true;
	}
	local_irq_restore(flags);
	return good;
}

/* non-SMP percpu_counter_add_local is the same with percpu_counter_add */
static inline void
percpu_counter_add_local(struct percpu_counter *fbc, s64 amount)
{
	percpu_counter_add(fbc, amount);
}

