/* 학습 해설
 * 공통 inc·dec·sub wrapper·부호와 단위의 계약
 * 공통 편의 API가 기본 갱신 경로에 어떤 signed amount를 넘기는지 배웁니다.
 * CONFIG 분기 뒤 공통 inc는 add(...,1), dec는 add(...,-1), sub는 add(...,-amount), sub_local은 add_local(...,-amount)를 호출합니다. 각 구성의 add가 실제 저장과 동기화를 담당하며 wrapper 자체는 별도 checked subtraction이나 lifetime 검사를 수행하지 않습니다.
 * 이벤트 단위를 일정하게 정해 inc/dec를 사용하고 큰 amount의 sub는 부호 반전과 합 범위를 먼저 확인합니다. 일반 sub와 local sub의 batching·읽기 규약을 선택한 뒤 같은 묶음 생명주기 안에서 호출합니다.
 */
static inline void percpu_counter_sub(struct percpu_counter *fbc, s64 amount)
{
	percpu_counter_add(fbc, -amount);
}

static inline void
percpu_counter_sub_local(struct percpu_counter *fbc, s64 amount)
{
	percpu_counter_add_local(fbc, -amount);
}

