/* 학습 해설
 * 최대 비율 포화 반올림·ceil로 인한 한 이벤트 차이
 * 제한 근처의 정수 이벤트 수를 올림으로 선택하는 실제 정책과 엄밀한 상한 차이를 배웁니다.
 * tmp가 요청 예산보다 작으면 nr=div_u64(tmp+BASE-max_frac-1,BASE-max_frac)로 올림 나눗셈합니다. 이 ceil 정책은 분수 상한을 한 이벤트 단위로 조금 넘을 수 있어 정확한 실수 상한 floor 제한과 다릅니다. 근사 카운터의 num/den 기반 판단까지 함께 고려해야 합니다.
 * num=1,den=5,max_frac=341,요청4에서 tmp=681,divisor=683,ceil=1을 계산합니다. 최종2/6은341/1024보다 조금 큽니다. helper를 엄밀한 quota나 완전한 비율 상한 API로 사용하는 가정을 검토합니다.
 */
void __fprop_add_percpu_max(struct fprop_global *p,
		struct fprop_local_percpu *pl, int max_frac, long nr)
{
	if (unlikely(max_frac < FPROP_FRAC_BASE)) {
		unsigned long numerator, denominator;
		s64 tmp;

		fprop_fraction_percpu(p, pl, &numerator, &denominator);
		/* Adding 'nr' to fraction exceeds max_frac/FPROP_FRAC_BASE? */
		tmp = (u64)denominator * max_frac -
					((u64)numerator << FPROP_FRAC_SHIFT);
		if (tmp < 0) {
			/* Maximum fraction already exceeded? */
			return;
		} else if (tmp < nr * (FPROP_FRAC_BASE - max_frac)) {
			/* Add just enough for the fraction to saturate */
			nr = div_u64(tmp + FPROP_FRAC_BASE - max_frac - 1,
					FPROP_FRAC_BASE - max_frac);
		}
	}

	__fprop_add_percpu(p, pl, nr);
}

